//! Dialects generated by `mlirformat tblgen` from LLVM 22.1.8 ODS (`tests/gen/*.gen.rs`): they
//! compile, and each fixture op of theirs either stays generic or prints exactly as `mlir-opt`
//! prints its custom form and parses back to the same op. Run with `--nocapture` for the table.
//!
//! Regenerate (from an llvm-project 22.1.8 checkout with `llvm-tblgen` built):
//!
//! ```text
//! mlirformat tblgen $LLVM/mlir/include/mlir/Dialect/Arith/IR/ArithOps.td -I $LLVM/mlir/include \
//!     --llvm-tblgen $LLVM/build/bin/llvm-tblgen -o tests/gen
//! ```

mod common;

#[path = "gen/affine.gen.rs"]
mod affine;
#[path = "gen/arith.gen.rs"]
mod arith;
#[path = "gen/async.gen.rs"]
mod r#async;
#[path = "gen/bufferization.gen.rs"]
mod bufferization;
#[path = "gen/cf.gen.rs"]
mod cf;
#[path = "gen/complex.gen.rs"]
mod complex;
#[path = "gen/func.gen.rs"]
mod func;
#[path = "gen/gpu.gen.rs"]
mod gpu;
#[path = "gen/index.gen.rs"]
mod index;
#[path = "gen/linalg.gen.rs"]
mod linalg;
#[path = "gen/llvm.gen.rs"]
mod llvm;
#[path = "gen/math.gen.rs"]
mod math;
#[path = "gen/memref.gen.rs"]
mod memref;
#[path = "gen/scf.gen.rs"]
mod scf;
#[path = "gen/shape.gen.rs"]
mod shape;
#[path = "gen/tensor.gen.rs"]
mod tensor;
#[path = "gen/tosa.gen.rs"]
mod tosa;
#[path = "gen/ub.gen.rs"]
mod ub;
#[path = "gen/vector.gen.rs"]
mod vector;

use std::collections::BTreeMap;

use common::{Fixtures, Verdict};
use mlirformat::MlirOpt;

/// Only the generated dialects.
fn generated() -> MlirOpt {
    let mut opt = MlirOpt::new();
    opt
        .register::<affine::Affine>()
        .register::<arith::Arith>()
        .register::<r#async::Async>()
        .register::<bufferization::Bufferization>()
        .register::<cf::Cf>()
        .register::<complex::Complex>()
        .register::<func::Func>()
        .register::<gpu::Gpu>()
        .register::<index::Index>()
        .register::<linalg::Linalg>()
        .register::<llvm::Llvm>()
        .register::<math::Math>()
        .register::<memref::Memref>()
        .register::<scf::Scf>()
        .register::<shape::Shape>()
        .register::<tensor::Tensor>()
        .register::<tosa::Tosa>()
        .register::<ub::Ub>()
        .register::<vector::Vector>()
        ;
    opt
}

#[derive(Default)]
struct Tally {
    ops: usize,
    unknown: usize,
    generic: usize,
    matched: usize,
    reparsed: usize,
    mismatch: Vec<String>,
    broken: Vec<String>,
}

#[test]
#[ignore = "slow: checks every fixture op of ~600 generated ops; run with --ignored"]
fn generated_dialects_match_mlir_opt() {
    let opt = generated();
    let registered: Vec<&str> = opt.namespaces().collect();
    let mut dialects: BTreeMap<String, Tally> = BTreeMap::new();
    Fixtures::each(|path, op, visible, custom| {
        let ns = op.name.split_once('.').map_or("", |(ns, _)| ns);
        if !registered.contains(&ns) {
            return;
        }
        let t = dialects.entry(ns.into()).or_default();
        t.ops += 1;
        match Fixtures::judge(&opt, op, visible, custom) {
            Verdict::Unknown => t.unknown += 1,
            Verdict::Generic => t.generic += 1,
            Verdict::Matched => t.matched += 1,
            Verdict::Reparsed => t.reparsed += 1,
            Verdict::Mismatch(text) => t.mismatch.push(format!("{}: {text}", path.file_name().unwrap().to_string_lossy())),
            Verdict::Broken(why) => t.broken.push(format!("{}: {why}", path.file_name().unwrap().to_string_lossy())),
        }
    });
    println!("{:<14} {:>7} {:>8} {:>8} {:>8} {:>8} {:>8} {:>7}", "dialect", "ops", "matched", "reparsed", "generic", "unknown", "mismatch", "broken");
    for (ns, t) in &dialects {
        println!("{ns:<14} {:>7} {:>8} {:>8} {:>8} {:>8} {:>8} {:>7}", t.ops, t.matched, t.reparsed, t.generic, t.unknown, t.mismatch.len(), t.broken.len());
    }
    let failures: Vec<&String> = dialects.values().flat_map(|t| t.broken.iter().chain(&t.mismatch)).collect();
    assert!(failures.is_empty(), "{} failures:\n{}", failures.len(), failures.iter().take(60).map(|s| s.as_str()).collect::<Vec<_>>().join("\n"));
}
